```python
def balanceado(s):
    pila = []
    for c in s:
        if c in "([":
            pila.append(c)
        elif c in ")]":
            if len(pila) == 0:
                return False
            abre = pila.pop()
            if (abre == "(" and c != ")") or (abre == "[" and c != "]"):
                return False
    return len(pila) == 0

s = input()
if balanceado(s):
    print("Balanceado")
else:
    print("No balanceado")
